        this.text = text;
        this.action = action;
    }

    public String getText() { return text; }
    public void execute() { action.run(); }
}
```

**Implementation:**
In your game loop, you print the options and wait for user input.

```java
import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class SimpleDialogue {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Define the dialogue
        List<DialogueOption> options = new ArrayList<>();
        options.add(new DialogueOption("Attack the Goblin", () -> {
            System.out.println("You swing your sword! The goblin screams.");
            // Add logic here
        }));
        options.add(new DialogueOption("Try to talk", () -> {
            System.out.println("You say 'Hello'. The goblin ignores you.");
            // Add logic here
        }));

        System.out.println("A goblin blocks your path.");
        System.out.println("What do you do?");

        for (int i = 0; i < options.size(); i++) {
            System.out.println((i + 1) + ". " + options.get(i).getText());
        }

        System.out.print("Enter choice (1-2): ");
        int choice = scanner.nextInt();

        if (choice >= 1 && choice <= options.size()) {
            options.get(choice - 1).execute();
        } else {
            System.out.println("Invalid choice.");
        }

        scanner.close();
    }
}
