      FROM hotels 
      WHERE name ILIKE $1 
      ORDER BY name 
      LIMIT 10
    `;

    const values = [`%${query}%`];

    const result = await client.query(queryText, values);
    client.release();

    res.json(result.rows);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

