Here is a complete, working example of a Go gRPC service that executes Ansible playbooks and streams the output to the client.

Since this is a complex system involving process management, networking, and concurrency, I have split this into **3 logical parts** (pages) to make it digestible.

### Prerequisites

You need Go installed and the Ansible Python library installed.

```bash
# Install Ansible
pip install ansible

# Initialize a Go module
go mod init ansible-grpc
```

---

### Page 1: The gRPC Service Definition & Server Logic

This file defines the `PlaybookService` and handles the execution of the Ansible command. It uses `exec.Command` to run Ansible and pipes the output to the gRPC stream.

**File:** `service.go`

```go
package main

import (
	"context"
	"fmt"
	"os/exec"
	"strings"
	"time"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// Define the gRPC Service
type PlaybookService struct{}

// Define the gRPC Methods
func (s *PlaybookService) RunPlaybook(stream PlaybookService_RunPlaybookServer) error {
	// 1. Receive the request
	req, err := stream.Recv()
	if err != nil {
		return status.Error(codes.InvalidArgument, "Failed to receive request")
	}

	// 2. Validate inputs
	if req.Playbook == "" {
		return status.Error(codes.InvalidArgument, "Playbook path is required")
	}

	// 3. Prepare the Ansible Command
	// We use -v for verbose output so the client sees the progress
	cmd := exec.Command("ansible-playbook", req.Playbook, "-v")

	// Optional: Add extra arguments if needed
	// cmd.Args = append(cmd.Args, "-e", "var=value")

	// 4. Create a context with timeout (e.g., 10 minutes)
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Minute)
	defer cancel()

	// 5. Start the command
	// We do not wait() immediately. We will stream the output.
	cmd.Stdout = stream
	cmd.Stderr = stream // Stream errors too

	if err := cmd.Start(); err != nil {
		return status.Error(codes.Internal, fmt.Sprintf("Failed to start ansible: %v", err))
	}

	// 6. Wait for the command to finish
	// We use a select loop to handle the context cancellation
	select {
	case <-ctx.Done():
		cmd.Process.Kill() // Kill the ansible process if timeout
		return status.Error(codes.DeadlineExceeded, "Playbook execution timed out")
	case err := <-cmd.Wait():
		if err != nil {
			// Ansible returns non-zero exit codes for failures
			return status.Error(codes.FailedPrecondition, fmt.Sprintf("Playbook failed with exit code: %d", err.(*exec.ExitError).ExitCode()))
		}
	}

	return nil
}

// Register the service
